// Explicit environment: PLAYWRIGHT_MODULE, GITDASH_TEST_ORIGIN, GITDASH_TEST_OUTPUT.
const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
const {chromium} = require(process.env.PLAYWRIGHT_MODULE);
const origin = process.env.GITDASH_TEST_ORIGIN;
const output = process.env.GITDASH_TEST_OUTPUT;
assert.ok(origin && output);
(async()=>{
 const browser = await chromium.launch({headless:true});
 const ctx = await browser.newContext({viewport:{width:1440,height:1000},timezoneId:'Asia/Tokyo',permissions:['clipboard-read','clipboard-write']});
 const page = await ctx.newPage(); page.setDefaultTimeout(15000);
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 const clipboard=()=>page.evaluate(()=>navigator.clipboard.readText());
 const passed=[];
 await fs.mkdir(output,{recursive:true});
 try {
  await page.goto(origin);
  await page.waitForFunction(()=>!document.querySelector('.workspace-export').disabled);
  await page.getByRole('searchbox',{name:'プロジェクトを検索',exact:true}).fill('/home/solution2024/git-manager');
  const downloadPromise=page.waitForEvent('download');
  await page.getByRole('button',{name:'表示中の一覧をCSV保存',exact:true}).click();
  const csv=await fs.readFile(await (await downloadPromise).path(),'utf8');
  assert.ok(csv.includes('"git-manager"') && csv.includes('"captured_at"'));
  await page.getByRole('button',{name:'表示中の一覧をMarkdownでコピー',exact:true}).click();
  assert.ok((await clipboard()).includes('# gitdash プロジェクト一覧'));
  assert.ok((await clipboard()).includes('/home/solution2024/git-manager'));
  passed.push('Workspace filtered CSV and Markdown clipboard');

  const card=page.locator('.project-card').filter({has:page.getByRole('heading',{name:'git-manager',exact:true})});
  const favorite=card.getByRole('button',{name:/お気に入り/});
  await favorite.click();
  await page.locator('.project-switch-trigger').click();
  const dialog=page.getByRole('dialog');
  await dialog.locator('.project-switch-results a').first().waitFor();
  await dialog.getByRole('button',{name:'☆ お気に入りのみ',exact:true}).click();
  await dialog.locator('.project-switch-results a').first().waitFor();
  assert.equal(await dialog.locator('.project-switch-results a').count(),1);
  assert.ok((await dialog.locator('.project-switch-results a').innerText()).includes('git-manager'));
  await dialog.getByRole('button',{name:'★ お気に入りのみ',exact:true}).click();
  await page.getByLabel('切り替え一覧の並び順').selectOption('name');
  const names=await dialog.locator('.project-switch-results a strong').allTextContents();assert.ok(names.length>1);
  const input=page.getByRole('searchbox',{name:'切り替えるプロジェクトを検索',exact:true});
  await input.focus();await input.press('ArrowDown');
  assert.equal(await page.evaluate(()=>document.activeElement===document.querySelector('.project-switch-results a')),true);
  await page.keyboard.press('End');
  assert.equal(await page.evaluate(()=>document.activeElement===[...document.querySelectorAll('.project-switch-results a')].at(-1)),true);
  await page.keyboard.press('Home');await page.keyboard.press('ArrowDown');await page.keyboard.press('ArrowUp');
  assert.equal(await page.evaluate(()=>document.activeElement===document.querySelector('.project-switch-results a')),true);
  await input.fill('git-manager');await input.press('Enter');
  await page.waitForURL('**/project?**');
  await page.locator('.project-switch-trigger').click();
  await dialog.locator('.project-switch-results a').first().waitFor();
  await dialog.getByRole('button',{name:/最近見たもの/}).click();
  assert.equal(await dialog.locator('.project-switch-results a').count(),1);
  await dialog.screenshot({path:`${output}/switcher.png`});
  await page.keyboard.press('Escape');
  assert.equal(await page.locator('.project-switch-trigger').evaluate(el=>el===document.activeElement),true);
  passed.push('Switcher live favorites, recent visits, explicit sorting, keyboard navigation/Enter/Escape focus');

  const guide=page.locator('.command-guide');await guide.locator('summary').click();
  const status=guide.locator('article').filter({has:page.getByRole('heading',{name:'変更の全体像',exact:true})});
  const log=guide.locator('article').filter({has:page.getByRole('heading',{name:'分岐と合流を見る',exact:true})});
  await status.getByRole('button',{name:'変更の全体像をお気に入りに追加'}).click();
  await status.getByRole('checkbox').check();await log.getByRole('checkbox').check();
  await guide.getByLabel('git logの表示件数').fill('42');
  await guide.locator('.command-guide-history-field').filter({has:page.getByLabel('git logの表示件数')}).getByRole('button',{name:'適用'}).click();
  assert.ok((await log.locator('code').innerText()).endsWith('-42'));
  await guide.getByLabel('git logの表示件数').fill('0');
  await guide.locator('.command-guide-history-field').filter({has:page.getByLabel('git logの表示件数')}).getByRole('button',{name:'適用'}).click();
  assert.ok((await guide.getByRole('alert').innerText()).includes('1〜500'));
  assert.ok((await log.locator('code').innerText()).endsWith('-42'));
  await guide.getByRole('button',{name:'☆ お気に入りのみ',exact:true}).click();
  assert.equal(await guide.locator('article').count(),1);
  await guide.getByRole('button',{name:'選択したコマンドをコピー',exact:true}).click();
  const batch=await clipboard();assert.ok(batch.includes("git -C '/home/solution2024/git-manager' status --short --branch"));assert.ok(batch.includes('-42'));assert.equal(batch.split('\n').length,2);
  const mdDownload=page.waitForEvent('download');await guide.getByRole('button',{name:'選択したコマンドをMarkdownでダウンロード',exact:true}).click();
  const md=await fs.readFile(await(await mdDownload).path(),'utf8');assert.ok(md.includes('## 分岐と合流を見る')&&md.includes('-42'));
  await guide.screenshot({path:`${output}/guide.png`});
  await page.setViewportSize({width:390,height:844});await guide.locator('summary').scrollIntoViewIfNeeded();await page.screenshot({path:`${output}/guide-mobile.png`});assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));await page.setViewportSize({width:1440,height:1000});
  await page.reload();await guide.locator('summary').click();
  await guide.getByRole('button',{name:'☆ お気に入りのみ',exact:true}).click();assert.equal(await guide.locator('article').count(),1);
  passed.push('Guide persisted favorites, selected batch including hidden commands, Markdown download, validated history count');

  await page.goto(`${origin}/project?path=%2Fhome%2Fsolution2024%2Fgit-manager&tab=info&range=current`);
  const pr=page.locator('.pr-explorer');await pr.locator('.pr-explorer-card').first().waitFor();
  await page.getByLabel('sourceブランチで絞り込む').selectOption({label:(await page.getByLabel('sourceブランチで絞り込む').locator('option').allTextContents()).find(x=>x.includes('codex/issues-5-8'))});
  assert.equal(await pr.locator('.pr-explorer-card').count(),1);
  await page.getByLabel('マージ日の開始日').fill('2026-09-03');await page.getByLabel('マージ日の終了日').fill('2026-09-03');
  assert.equal(await pr.locator('.pr-explorer-card').count(),1);
  await pr.getByRole('button',{name:'表示中の1件のPR URLをコピー',exact:true}).click();assert.ok((await clipboard()).endsWith('/pull/10'));
  await pr.getByRole('button',{name:'コンパクト表',exact:true}).click();assert.equal(await pr.locator('tbody tr').count(),1);
  assert.equal(await pr.getByRole('link',{name:/PR #10/}).count(),1);
  await page.getByLabel('マージ日の開始日').fill('2026-09-04');assert.ok((await pr.getByRole('alert').innerText()).includes('開始日は終了日以前'));
  assert.equal(await pr.locator('tbody tr').count(),0);
  await pr.getByRole('button',{name:'条件をすべて解除',exact:true}).click();assert.ok(await pr.locator('tbody tr').count()>1);
  await pr.locator('.pr-explorer-heading').scrollIntoViewIfNeeded();await page.screenshot({path:`${output}/pr.png`});
  await page.setViewportSize({width:390,height:844});await pr.locator('.pr-explorer-heading').scrollIntoViewIfNeeded();await page.screenshot({path:`${output}/pr-mobile.png`});
  assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));
  await page.locator('.project-switch-trigger').click();await dialog.locator('.project-switch-results a').first().waitFor();await page.screenshot({path:`${output}/switcher-mobile.png`});
  assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));
  passed.push('PR exact source/date boundaries/invalid range, URL clipboard, compact table, responsive UI');
  assert.deepEqual(errors,[]);await fs.writeFile(`${output}/result.json`,JSON.stringify({origin,passed,errors},null,2));console.log({passed,errors});
 }catch(e){await page.screenshot({path:`${output}/failure.png`});console.error(e);console.error((await page.locator('body').innerText()).slice(-1800));process.exitCode=1;}
 finally{await browser.close();}
})();
